// Procesar entrada del usuario web
const userMessage = $input.all()[0].json.body.message;
const sessionId = $input.all()[0].json.body.sessionId || 'web-session-' + Date.now();
const fileUploads = $input.all()[0].json.body.files || [];
const userId = $input.all()[0].json.body.userId || 'anonymous';

// Clasificar tipo de consulta
let queryType = 'general';
if (userMessage.toLowerCase().includes('conciliar') || userMessage.toLowerCase().includes('banco')) {
  queryType = 'reconciliation';
} else if (userMessage.toLowerCase().includes('reporte') || userMessage.toLowerCase().includes('gráfico')) {
  queryType = 'reporting';
} else if (userMessage.toLowerCase().includes('flujo') || userMessage.toLowerCase().includes('efectivo')) {
  queryType = 'cashflow';
}

return [{
  message: userMessage,
  sessionId: sessionId,
  userId: userId,
  queryType: queryType,
  files: fileUploads,
  timestamp: new Date().toISOString(),
  country: 'mexico'
}];

// Procesar archivos financieros mexicanos
const files = $input.all()[0].json.files;
const processedFiles = [];

for (const file of files) {
  let fileType = 'unknown';
  let extractedData = {};

  // Identificar tipo de archivo
  if (file.name.endsWith('.xml')) {
    fileType = 'cfdi';
    // Simular extracción de datos CFDI
    extractedData = {
      rfc_emisor: 'XAXX010101000',
      rfc_receptor: 'XEXX010101000',
      total: 1160.00,
      moneda: 'MXN',
      fecha: '2024-03-15T10:30:00',
      conceptos: ['Servicios profesionales'],
      regimen_fiscal: '601'
    };
  } else if (file.name.includes('estado') || file.name.includes('bank')) {
    fileType = 'bank_statement';
    extractedData = {
      banco: 'BBVA México',
      cuenta: '****1234',
      periodo: '2024-03',
      saldo_inicial: 25000.00,
      saldo_final: 28500.00,
      transacciones: 45
    };
  }

  processedFiles.push({
    original: file,
    type: fileType,
    data: extractedData,
    processed_at: new Date().toISOString()
  });
}

return [{
  ...($input.all()[0].json),
  processed_files: processedFiles,
  file_processing_complete: true
}];

// Generar configuración de gráficos financieros
const agentResponse = $input.all()[0].json.output;
const queryType = $input.all()[0].json.queryType;

let chartConfig = null;

// Detectar si se necesita un gráfico
if (agentResponse.toLowerCase().includes('gráfico') || 
    agentResponse.toLowerCase().includes('chart') ||
    queryType === 'reporting') {

  // Generar configuración Chart.js
  if (queryType === 'cashflow') {
    chartConfig = {
      type: 'line',
      data: {
        labels: ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun'],
        datasets: [{
          label: 'Flujo de Efectivo (MXN)',
          data: [25000, 28000, 22000, 35000, 40000, 38000],
          borderColor: 'rgb(75, 192, 192)',
          backgroundColor: 'rgba(75, 192, 192, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        plugins: {
          title: {
            display: true,
            text: 'Flujo de Efectivo - Empresa México'
          }
        },
        scales: {
          y: {
            ticks: {
              callback: function(value) {
                return '$' + value.toLocaleString('es-MX');
              }
            }
          }
        }
      }
    };
  } else if (queryType === 'reporting') {
    chartConfig = {
      type: 'bar',
      data: {
        labels: ['Q1', 'Q2', 'Q3', 'Q4'],
        datasets: [{
          label: 'Ingresos (MXN)',
          data: [120000, 150000, 135000, 180000],
          backgroundColor: 'rgba(54, 162, 235, 0.8)'
        }]
      },
      options: {
        responsive: true,
        plugins: {
          title: {
            display: true,
            text: 'Ingresos Trimestrales 2024'
          }
        }
      }
    };
  }
}

return [{
  response: agentResponse,
  chartConfig: chartConfig,
  hasChart: chartConfig !== null,
  timestamp: new Date().toISOString(),
  queryType: queryType
}];

// Formatear respuesta para chatbot web
const data = $input.all()[0].json;

const webResponse = {
  success: true,
  data: {
    message: data.response,
    timestamp: new Date().toISOString(),
    session_id: data.sessionId || 'web-session',
    has_chart: data.hasChart || false,
    chart_config: data.chartConfig || null,
    query_type: data.queryType || 'general',
    suggestions: [
      '📊 Ver dashboard financiero',
      '🏦 Iniciar conciliación bancaria',
      '📈 Generar reporte mensual',
      '💰 Analizar flujo de efectivo'
    ],
    actions: [
      {
        type: 'download',
        label: 'Descargar reporte PDF',
        endpoint: '/api/reports/pdf'
      },
      {
        type: 'upload',
        label: 'Subir más archivos',
        accept: '.xml,.pdf,.csv,.xlsx'
      }
    ]
  }
};

return [webResponse];

// Procesar entrada de Telegram (consultas rápidas)
const message = $input.all()[0].json.message;

// Convertir comandos de Telegram a formato web
let webFormat = {
  message: message.text,
  sessionId: 'telegram-' + message.from.id,
  userId: message.from.id.toString(),
  queryType: 'quick_query',
  files: [],
  platform: 'telegram',
  timestamp: new Date().toISOString(),
  country: 'mexico'
};

// Detectar comandos rápidos
if (message.text.startsWith('/')) {
  const command = message.text.toLowerCase();
  if (command.includes('ventas')) {
    webFormat.message = 'Mostrar resumen de ventas del día';
    webFormat.queryType = 'reporting';
  } else if (command.includes('saldo')) {
    webFormat.message = 'Consultar saldo actual de cuentas';
    webFormat.queryType = 'balance';
  } else if (command.includes('alertas')) {
    webFormat.message = 'Mostrar alertas pendientes';
    webFormat.queryType = 'alerts';
  }
}

return [webFormat];

